const int LIMIT = 1000000;
vector<int> primes;

void get_primes() {
    // 埃氏筛预处理所有不超过 10^6 的基源数（素数）
    vector<bool> is_prime(LIMIT + 1, true);
    is_prime[0] = false;
    is_prime[1] = false;

    for (int i = 2; i * i <= LIMIT; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= LIMIT; j += i) {
                is_prime[j] = false;
            }
        }
    }

    for (int i = 2; i <= LIMIT; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
        }
    }
}

bool check_prime(long long x) {
    // 判断 x 是否为基源数（x <= 10^9）
    if (x < 2) return false;

    for (int p : primes) {
        if (1LL * p * p > x) break;
        if (x % p == 0) return false;
    }
    return true;
}

vector<long long> solve_one(long long n) {
    vector<long long> ans;
    long long x = n;

    // 处理所有不超过 10^6 的基源数
    for (int p : primes) {
        long long pp = 1LL * p * p;
        if (pp > x) break;

        int cnt = 0;
        while (x % p == 0) {
            x /= p;
            cnt++;
        }

        // 若基源数 p 至少出现 2 次，则 p^2 是基方因子
        if (cnt >= 2) {
            ans.push_back(pp);
        }
    }

    // 剩余部分可能是一个大基源数的平方
    long long r = sqrt((long double)x);
    while ((r + 1) <= x / (r + 1)) r++;
    while (r > x / r) r--;

    if (r * r == x && check_prime(r)) {
        ans.push_back(x);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    get_primes();

    int T;
    cin >> T;

    while (T--) {
        long long n;
        cin >> n;

        vector<long long> ans = solve_one(n);

        if (ans.empty()) {
            cout << -1;
